MAX_ATTEMPTS = 4
_BACKOFF = (1, 2, 4)  # waits before attempts 2, 3 and 4
_SERVER_ERRORS = (500, 502, 503, 504)


def _key(operation: str, reference: str) -> str:
    return f"pl-{operation}-{hashlib.sha256(reference.encode('utf-8')).hexdigest()[:24]}"


def _error(r: Response) -> ApiError:
    try:
        code = str(json.loads(r.body)["error"]["code"])
    except (ValueError, KeyError, TypeError):
        code = ""
    return ApiError(r.status, code)


def _wait(transport: Transport, attempt: int, r: Response | None) -> None:
    """Waits before attempt `attempt + 1`, after attempt `attempt` failed with `r` (None: no response)."""
    seconds: float = _BACKOFF[attempt - 1]
    if r is not None:
        for name, value in r.headers.items():
            if name.lower() == "retry-after":
                try:
                    seconds = int(str(value).strip())
                except ValueError:
                    pass
                break
    transport.sleep(seconds)


def _send(transport: Transport, method: str, path: str, headers: dict[str, str], body: dict[str, Any] | None) -> Response | None:
    try:
        return transport.send(method, path, dict(headers), body)
    except ConnectionError:
        return None


def _call(
    transport: Transport, method: str, path: str, body: dict[str, Any] | None = None, key: str | None = None
) -> Any:
    headers = {"Idempotency-Key": key} if key is not None else {}
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            r = transport.send(method, path, dict(headers), body)
        except ConnectionError:
            if attempt == MAX_ATTEMPTS:
                raise
            _wait(transport, attempt, None)
            continue
        if r.status in (200, 201):
            return json.loads(r.body)
        err = _error(r)
        retryable = r.status in _SERVER_ERRORS or r.status == 429 or (r.status == 409 and err.code == "idempotency_in_progress")
        if not retryable or attempt == MAX_ATTEMPTS:
            raise err
        _wait(transport, attempt, r)
    raise AssertionError("unreachable")

path = f"{BASE}/transfers/{transfer_id}/reversal"
for attempt in range(1, MAX_ATTEMPTS + 1):
    r = _send(transport, "POST", path, {}, None)
    if r is not None and r.status in (200, 201):
        return _transfer(json.loads(r.body))
    if r is not None and r.status != 429 and r.status not in _SERVER_ERRORS:
        raise _error(r)
    if attempt == MAX_ATTEMPTS:
        if r is None:
            raise ConnectionError("no response")
        raise _error(r)
    _wait(transport, attempt, r)
    if r is None or r.status != 429:
        # The reversal may have been applied: read the transfer before sending it again.
        current = get_transfer(transport, transfer_id)
        if current.status == "reversed":
            return current
raise AssertionError("unreachable")

